function change(items,label,record=true){const done=[];for(const x of items){const old=raw(x.address),value=String(x.value??'');if(old!==value){put(x.address,value);S.dirty.add(x.address);done.push({address:x.address,old,value})}}if(!done.length)return;if(record){S.undo.push({label,changes:done});S.redo=[]}status('dirty');render();clearTimeout(S.timer);S.timer=setTimeout(save,900)}
function undo(){const a=S.undo.pop();if(!a)return;for(const x of a.changes){put(x.address,x.old);S.dirty.add(x.address)}S.redo.push(a);status('dirty');render();clearTimeout(S.timer);S.timer=setTimeout(save,900)}
function redo(){const a=S.redo.pop();if(!a)return;for(const x of a.changes){put(x.address,x.value);S.dirty.add(x.address)}S.undo.push(a);status('dirty');render();clearTimeout(S.timer);S.timer=setTimeout(save,900)}
function selectionItems(fn){const b=bounds(),o=[];for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++)o.push({address:F.address(r,c),value:fn(r,c)});return o}
function edit(seed=null){const a=F.address(S.sel.r2,S.sel.c2),ce=cell(S.sel.r2,S.sel.c2),ed=$('editor'),wrap=$('grid-wrap'),cr=ce.getBoundingClientRect(),wr=wrap.getBoundingClientRect();S.editing=true;ed.style.cssText=`display:block;left:${cr.left-wr.left+wrap.scrollLeft}px;top:${cr.top-wr.top+wrap.scrollTop}px;width:${Math.max(cr.width,180)}px;height:${cr.height}px`;ed.value=seed===null?raw(a):seed;ed.dataset.address=a;ed.focus();ed.select();assist()}
function commit(move=0){if(!S.editing)return;const ed=$('editor'),a=ed.dataset.address;S.editing=false;ed.style.display='none';$('suggestions').style.display='none';change([{address:a,value:ed.value}],`Edit ${a}`);$('grid-wrap').focus();if(move){const p=F.parseAddr(a);select(p.r+move,p.c)}}
function cancel(){S.editing=false;$('editor').style.display='none';$('suggestions').style.display='none';render();$('grid-wrap').focus()}
function assist(){const ed=$('editor'),box=$('suggestions');if(!S.editing||!ed.value.startsWith('=')){box.style.display='none';render();return}const m=/([A-Za-z]*)$/.exec(ed.value),p=m?.[1].toUpperCase(),list=F.FUNCS.filter(x=>x.startsWith(p));if(p&&list.length){box.innerHTML=list.map(x=>`<div class="suggestion" data-f="${x}">${x}</div>`).join('');box.style.display='block';box.style.left=ed.style.left;box.style.top=`${parseFloat(ed.style.top)+28}px`}else box.style.display='none';render()}
function insertRef(ref){const e=$('editor'),pos=e.selectionStart,left=e.value.slice(0,pos),right=e.value.slice(e.selectionEnd),m=left.match(/[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?$/i),start=m?pos-m[0].length:pos;e.value=left.slice(0,start)+ref+right;e.selectionStart=e.selectionEnd=start+ref.length;e.focus();assist()}
async function copy(cut=false){const b=bounds(),rows=[];for(let r=b.r1;r<=b.r2;r++){const x=[];for(let c=b.c1;c<=b.c2;c++)x.push(raw(F.address(r,c)));rows.push(x.join('\t'))}try{await navigator.clipboard.writeText(rows.join('\n'));if(cut)change(selectionItems(()=>''),'Cut range');msg(cut?'Range cut':'Range copied')}catch{msg('Clipboard permission denied',true)}}
function pasteText(t){const rows=t.replace(/\r/g,'').split('\n').filter((x,i,a)=>x!==''||i<a.length-1),p=F.parseAddr(F.address(S.sel.r2,S.sel.c2)),out=[];rows.forEach((line,ri)=>(line.includes('\t')?line.split('\t'):line.includes(',')?line.split(','):line.split(';')).forEach((v,ci)=>{if(p.r+ri<=ROWS&&p.c+ci<=COLS)out.push({address:F.address(p.r+ri,p.c+ci),value:v})}));change(out,'Paste range')}
async function paste(){try{pasteText(await navigator.clipboard.readText())}catch{msg('Clipboard permission denied',true)}}
function fill(dir){const b=bounds(),vert=dir==='down',lanes=vert?Array.from({length:b.c2-b.c1+1},(_,i)=>b.c1+i):Array.from({length:b.r2-b.r1+1},(_,i)=>b.r1+i),out=[];for(const lane of lanes){const len=vert?b.r2-b.r1+1:b.c2-b.c1+1,at=i=>vert?F.address(b.r1+i,lane):F.address(lane,b.c1+i);if(len<2)continue;const x=raw(at(0)),y=raw(at(1)),num=x!==''&&y!==''&&Number.isFinite(+x)&&Number.isFinite(+y),step=num?+y-+x:0,sp=F.parseAddr(at(0));for(let i=1;i<len;i++){const tp=F.parseAddr(at(i)),v=num?String(+x+step*i):x.startsWith('=')?F.adjust(x,tp.r-sp.r,tp.c-sp.c):x;out.push({address:at(i),value:v})}}change(out,`Fill ${dir}`)}
